	@Test
	void twoPatternJoinRetainsTheRootDomainExistsAlternative() throws Exception {
		String bagQuery = "SELECT ?root ?w WHERE { ?root <" + EX + "type> <" + EX
				+ "eligible> . ?root <" + EX + "hasWitness> ?w }";
		String countQuery = "SELECT (COUNT(DISTINCT ?root) AS ?count) WHERE { ?root <" + EX
				+ "type> <" + EX + "eligible> . ?root <" + EX + "hasWitness> ?w }";
		try (Fixture fixture = new Fixture(directory)) {
			List<BindingSet> fullBag = fixture.rows(bagQuery, false);
			List<BindingSet> broadRelation = fixture.rows(BROAD_RELATION_QUERY, false);
			List<BindingSet> eligibleRoots = fixture.rows(ELIGIBLE_ROOTS_QUERY, false);
			Set<Value> matchedRoots = new HashSet<>();
			for (BindingSet row : fullBag) {
				matchedRoots.add(row.getValue("root"));
			}
			long genericCount = fixture.count(countQuery, false);
			long nativeCount = fixture.count(countQuery, true);

			assertEquals(450, fullBag.size(), "the full bag retains all repeated witnesses for eligible roots");
			assertEquals(600, broadRelation.size(), "the broad witness scan emits every stored witness row");
			assertEquals(12, eligibleRoots.size(), "the counted-root pattern supplies an exact selective domain");
			assertEquals(9, matchedRoots.size(), "eligible roots without witnesses do not contribute");
			assertEquals(matchedRoots.size(), genericCount, "generic COUNT(DISTINCT) agrees with the full bag");
			assertEquals(genericCount, nativeCount, "native COUNT(DISTINCT) agrees with generic evaluation");

			// The root-first plan emits each of 12 eligible roots once, then performs at most one correlated
			// existence probe per root. These are operation counts, not qualified work-row estimates.
			long rootEnumerationOperations = eligibleRoots.size();
			long rootExistenceProbeOperations = eligibleRoots.size();
			assertEquals(24, rootEnumerationOperations + rootExistenceProbeOperations,
					"each eligible key is enumerated once and receives at most one existence probe");

			try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(fixture.store)) {
				NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
				var tripleSource = new SailDatasetTripleTermSource(fixture.repository.getValueFactory(), dataset);
				var strategy = new LmdbNativeEvaluationStrategy(tripleSource, null, null, 0L,
						new EvaluationStatistics(), false);
				var compiler = new LmdbNativeAggregatePlanner(new QueryEvaluationContext.Minimal((Dataset) null),
						strategy, source);
				List<StatementPattern> parsedPatterns = parsePatterns(bagQuery);
				StatementPattern rootDomainPattern = byPredicate(parsedPatterns, "type");
				StatementPattern witnessPattern = byPredicate(parsedPatterns, "hasWitness");
				SlotPlan rootDomain = compiler.compileTuple(rootDomainPattern, false);
				SlotPlan witness = compiler.compileTuple(witnessPattern, false);
				assertTrue(rootDomain instanceof PatternPlan && witness instanceof PatternPlan,
						"SETUP: the two parsed mandatory patterns compile to native pattern plans");
				compiler.layout.freeze(compiler.slotNames);
				int rootSlot = compiler.existingSlot("root");
				RowState row = new RowState(source, compiler.layout, EmptyBindingSet.getInstance());
				assertTrue(LmdbNativeAggregateCompiler.initializeRow(row, row.base, source, compiler.layout));
				AggregateSpec[] aggregates = { AggregateSpec.slot("count", rootSlot, true, AggKind.COUNT) };

			SlotPlan rootedPlan = new MultiJoinPlan(new SlotPlan[] { rootDomain, witness }, new MaskedFilter[0]);
			LmdbNativeKernelLowering.Lowered rootFirst = LmdbNativeKernelLowering.lowerAggregate(rootedPlan, row,
					new int[0], aggregates, null);
				assertNotNull(rootFirst, "SETUP: the root-domain alternative lowers through the native aggregate rung");
				assertRootDomainExistsCount(rootFirst.kernel);

				SlotPlan broadPlan = new MultiJoinPlan(new SlotPlan[] { witness, rootDomain }, new MaskedFilter[0]);
				LmdbNativeWork.Chain broadWork = LmdbNativeWork.chain(((MultiJoinPlan) broadPlan).children, 2, row,
						row.boundMask());
				LmdbNativeWork.Chain rootedWork = LmdbNativeWork.chain(((MultiJoinPlan) rootedPlan).children, 2, row,
						row.boundMask());
				SlotPlan selectedInput = LmdbNativeNeutralRangeOrder.prepareAggregate(broadPlan, row, row.boundMask(),
						aggregates);
				LmdbNativeKernelLowering.Lowered selected = LmdbNativeKernelLowering.lowerAggregate(selectedInput, row,
						new int[0], aggregates, null);
				assertNotNull(selected, "SETUP: the deliberately broad-first aggregate lowers natively");
				System.out.println("DISTINCT_ROOT_TWO_PATTERN_ALTERNATIVE {\"bagRows\":" + fullBag.size()
						+ ",\"genericCount\":" + genericCount + ",\"nativeCount\":" + nativeCount
						+ ",\"eligibleRootDomain\":" + eligibleRoots.size() + ",\"matchingRoots\":"
						+ matchedRoots.size() + ",\"broadWitnessRows\":" + broadRelation.size()
						+ ",\"rootEnumerationOperations\":" + rootEnumerationOperations
						+ ",\"rootExistenceProbeOperations\":" + rootExistenceProbeOperations
						+ ",\"broadEstimatedWork\":" + quote(Double.toString(broadWork.estimatedWork()))
						+ ",\"broadEstimatedPriceable\":" + broadWork.estimatedPriceable()
						+ ",\"rootedEstimatedWork\":" + quote(Double.toString(rootedWork.estimatedWork()))
						+ ",\"rootedEstimatedPriceable\":" + rootedWork.estimatedPriceable()
						+ ",\"broadConservativeWork\":" + quote(broadWork.work().toString())
						+ ",\"rootedConservativeWork\":" + quote(rootedWork.work().toString())
						+ ",\"candidateShape\":" + quote(rootFirst.kernel.shapeKey())
						+ ",\"currentShape\":" + quote(selected.kernel.shapeKey()) + "}");

				// Intended pre-fix red: the broad-first two-pattern input is not replaced with its valid
				// root-domain plus positive-existence physical alternative.
				assertRootDomainExistsCount(selected.kernel);
			}
		}
	}

	@Test
	void medicalShapedOptionalNullRejectionAndMinusRetainTheExpectedCount() throws Exception {
		String query = "SELECT (COUNT(DISTINCT ?root) AS ?count) WHERE { "
				+ "?root <" + EX + "type> <" + EX + "eligible> . "
				+ "OPTIONAL { ?root <" + EX + "hasWitness> ?w . ?w <" + EX + "accepted> <" + EX + "yes> } "
				+ "FILTER(BOUND(?w)) "
				+ "MINUS { ?root <" + EX + "blocked> <" + EX + "yes> } }";
		try (Fixture fixture = new Fixture(directory)) {
			long genericCount = fixture.count(query, false);
			long nativeCount = fixture.count(query, true);
			assertEquals(8L, genericCount, "the null-rejecting filter keeps nine witnessed roots and MINUS removes one");
			assertEquals(genericCount, nativeCount, "the medical-shaped native aggregate preserves expected semantics");
			try (SailRepositoryConnection connection = fixture.repository.getConnection()) {
				SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(QueryLanguage.SPARQL, query);
				Explanation explanation = prepared.explain(Explanation.Level.Telemetry);
				System.out.println("DISTINCT_ROOT_MEDICAL_SHAPE {\"expectedCount\":" + nativeCount
						+ ",\"actualTelemetry\":" + quote(explanation.toJson()) + "}");
			}
		}
	}

