	@Test
	void duplicateSameStatementInTwoContextsPreservesBagAndDistinctRootSemantics() throws Exception {
		IRI firstContext = org.eclipse.rdf4j.model.impl.SimpleValueFactory.getInstance().createIRI(EX, "context-1");
		IRI secondContext = org.eclipse.rdf4j.model.impl.SimpleValueFactory.getInstance().createIRI(EX, "context-2");
		IRI root = org.eclipse.rdf4j.model.impl.SimpleValueFactory.getInstance().createIRI(EX, "root-0");
		IRI type = org.eclipse.rdf4j.model.impl.SimpleValueFactory.getInstance().createIRI(EX, "type");
		IRI eligible = org.eclipse.rdf4j.model.impl.SimpleValueFactory.getInstance().createIRI(EX, "eligible");
		String bagQuery = "SELECT ?root ?w WHERE { { GRAPH <" + firstContext + "> { ?root <" + type + "> <"
				+ eligible + "> } ?root <" + EX + "hasWitness> ?w } UNION { GRAPH <" + secondContext
				+ "> { ?root <" + type + "> <" + eligible + "> } ?root <" + EX + "hasWitness> ?w } }";
		String countQuery = "SELECT (COUNT(DISTINCT ?root) AS ?count) WHERE { { GRAPH <" + firstContext
				+ "> { ?root <" + type + "> <" + eligible + "> } ?root <" + EX + "hasWitness> ?w } UNION { GRAPH <"
				+ secondContext + "> { ?root <" + type + "> <" + eligible + "> } ?root <" + EX
				+ "hasWitness> ?w } }";
		try (Fixture fixture = new Fixture(directory)) {
			try (SailRepositoryConnection connection = fixture.repository.getConnection()) {
				connection.begin();
				connection.add(root, type, eligible, firstContext);
				connection.add(root, type, eligible, secondContext);
				connection.commit();
			}
			List<BindingSet> fullBag = fixture.rows(bagQuery, false);
			assertEquals(100, fullBag.size(), "the repeated SPO in two contexts preserves both graph witnesses");
			long genericCount = fixture.count(countQuery, false);
			long nativeCount = fixture.count(countQuery, true);
			assertEquals(1L, genericCount, "the same RDF root in two contexts contributes one distinct root");
			assertEquals(genericCount, nativeCount, "native lowering preserves cross-context duplicate semantics");
		}
	}

	@Test
	void mixedAggregateAndOpaqueFilterBlockAlternativePreparation() throws Exception {
		try (Fixture fixture = new Fixture(directory);
				SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(fixture.store)) {
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			var tripleSource = new SailDatasetTripleTermSource(fixture.repository.getValueFactory(), dataset);
			var strategy = new LmdbNativeEvaluationStrategy(tripleSource, null, null, 0L,
					new EvaluationStatistics(), false);
			var compiler = new LmdbNativeAggregatePlanner(new QueryEvaluationContext.Minimal((Dataset) null), strategy,
					source);
			List<StatementPattern> parsedPatterns = parsePatterns(
					"SELECT ?root ?w WHERE { ?root <" + EX + "type> <" + EX
							+ "eligible> . ?root <" + EX + "hasWitness> ?w }");
			SlotPlan witness = compiler.compileTuple(byPredicate(parsedPatterns, "hasWitness"), false);
			SlotPlan rootDomain = compiler.compileTuple(byPredicate(parsedPatterns, "type"), false);
			compiler.layout.freeze(compiler.slotNames);
			RowState row = new RowState(source, compiler.layout, EmptyBindingSet.getInstance());
			assertTrue(LmdbNativeAggregateCompiler.initializeRow(row, row.base, source, compiler.layout));
			int rootSlot = compiler.existingSlot("root");
			AggregateSpec distinctRoot = AggregateSpec.slot("distinct", rootSlot, true, AggKind.COUNT);
			SlotPlan broadPlan = new MultiJoinPlan(new SlotPlan[] { witness, rootDomain }, new MaskedFilter[0]);
			MapBindingSet input = new MapBindingSet();
			input.addBinding("root", fixture.repository.getValueFactory().createIRI(EX, "root-0"));
			RowState boundRow = new RowState(source, compiler.layout, input);
			assertTrue(LmdbNativeAggregateCompiler.initializeRow(boundRow, boundRow.base, source, compiler.layout));
			assertTrue(boundRow.boundMask() != 0L, "SETUP: the counted root arrives already bound");
			assertSame(broadPlan,
					LmdbNativeNeutralRangeOrder.prepareAggregate(broadPlan, boundRow, boundRow.boundMask(),
							new AggregateSpec[] { distinctRoot }),
					"a pre-bound counted slot must not be replaced with a new root-domain enumeration");

			AggregateSpec[] mixedAggregates = { distinctRoot, AggregateSpec.star("rows") };
			assertSame(broadPlan,
					LmdbNativeNeutralRangeOrder.prepareAggregate(broadPlan, row, row.boundMask(), mixedAggregates),
					"COUNT(*) must retain witness multiplicity when paired with COUNT(DISTINCT root)");

			AtomicInteger opaqueCalls = new AtomicInteger();
			FilterPlan opaque = new FilterPlan(broadPlan, ignored -> {
				opaqueCalls.incrementAndGet();
				return true;
			}, -1L);
			assertSame(opaque, LmdbNativeNeutralRangeOrder.prepareAggregate(opaque, row, row.boundMask(),
					new AggregateSpec[] { distinctRoot }),
				"an opaque side-effecting filter remains a lexical barrier to reordering");
			assertEquals(0, opaqueCalls.get(), "preparation must never evaluate the side-effecting filter");
		}
	}

	private static void assertRootDomainExistsCount(Kernel kernel) {
		assertEquals(2, kernel.pipeline.size(), () -> "expected root domain plus existential witness: " + kernel.shapeKey());
		assertTrue(kernel.pipeline.get(0) instanceof EnumerateDomain, kernel.shapeKey());
		assertTrue(kernel.pipeline.get(1) instanceof Exists, kernel.shapeKey());
		assertFalse(((Exists) kernel.pipeline.get(1)).negated, "the remaining flat join is a positive witness");
		Aggregate aggregate = (Aggregate) kernel.terminal;
		AggregateOutput output = aggregate.outputs[0];
		assertEquals(LmdbNativeKernelIr.AGG_COUNT_DISTINCT, output.kind,
				"the exact root domain retains distinct-key semantics");
		assertEquals(((EnumerateDomain) kernel.pipeline.get(0)).domain, output.orderedDomain,
				"the aggregate uses the root domain's ordered DISTINCT channel");
	}

	private static List<StatementPattern> parsePatterns(String query) {
		TupleExpr expression = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
		List<StatementPattern> patterns = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern node) {
				patterns.add(node);
			}
		});
		return patterns;
	}

	private static StatementPattern byPredicate(List<StatementPattern> patterns, String localName) {
		return patterns.stream()
				.filter(pattern -> pattern.getPredicateVar().getValue() != null
						&& pattern.getPredicateVar().getValue().stringValue().equals(EX + localName))
				.findFirst()
				.orElseThrow(() -> new AssertionError("SETUP: missing parsed predicate " + localName));
	}

